def need(v,m):
 if not v: raise AssertionError(m)
def one(rows,m):
 need(len(rows)==1,m);return rows[0]
def source(row):
 s=row['before'];b=row['binding'];e=row['expected'];a=json.loads(s['capture']['native']['source']);need(a['version']==3 and len(a['stages'])==1,'source stage/version');need([[o['id'],o['type'],o['role'],o['stage']] for o in a['objects']]==b['objects'],'actual stable object identities');need(a['metadata']['boundaryFrame']==b['frame'],'actual source frame');need(a['stages'][0]['generators']==[],'no generated fixture source');objects={o['id']:o for o in a['objects']};need(objects[b['unrelatedObject']]['data']=={'x':77,'y':99},'unrelated Point exact');need(all(objects[o['id']]==o for o in b['baselineObjects']),'anchored rectangle source preserved');need(s['capture']['native']['history'][0]['type']=='PLANE' and len(s['capture']['native']['history'])==1,'one actual plane history');need(s['capture']['solids']['bodies']==[],'no fabricated BRep solids');need(not s['ownership']['processing'] and not s['ownership']['resources']['cleanupFailed'] and all(s['ownership']['resources'][k]==0 for k in ('accepted','candidates','mounts')),'settled resources');
 p=objects[b['aObject']]['data'];q=objects[b['bObject']]['data'];cs=a['stages'][0]['constraints'];ds=[c for c in cs if c['typeId']=='DistancePP'];need(len(ds)==(0 if e['distance'] is None else 1),'distance row census');need(len(cs)==len(b['baselineConstraints'])+len(b['locks'])+len(ds),'retained row census');base=[{k:v for k,v in c.items() if k!='admission'} for c in cs[:len(b['baselineConstraints'])]];need(base==b['baselineConstraints'],'retained datum constraints');pts={b['ids'][0]:p,b['ids'][1]:q};
 if b.get('datumId'):pts[b['datumId']]={'x':0,'y':0}
